import sys

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n, t = map(int, data)

    # amount[i][j] = champagne in j-th glass of i-th level (0-indexed)
    amount = [[0.0] * (i + 1) for i in range(n)]
    amount[0][0] = float(t)

    full = 0

    for i in range(n):
        for j in range(i + 1):
            if amount[i][j] >= 1.0:
                full += 1
                overflow = amount[i][j] - 1.0
                if i + 1 < n:
                    amount[i + 1][j] += overflow / 2.0
                    amount[i + 1][j + 1] += overflow / 2.0

    print(full)

if __name__ == "__main__":
    main()
